using Microsoft.EntityFrameworkCore;

public sealed class DeactivateStaleCustomers(ShopDb db)
{
    public async Task<int> RunAsync(DateTime cutoff, CancellationToken ct)
    {
        // Loads, materializes and snapshots every matching row
        var stale = await db.Customers
            .Where(c => c.IsActive && c.LastSeenAt < cutoff)
            .ToListAsync(ct);
        foreach (var customer in stale)
            customer.IsActive = false;
        // One UPDATE per customer, sent in batches
        return await db.SaveChangesAsync(ct);
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class DeactivateStaleCustomers(ShopDb db)
{
    public async Task<int> RunAsync(DateTime cutoff, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        // One UPDATE ... WHERE; nothing is loaded or tracked
        return await db.Customers
            .Where(c => c.IsActive && c.LastSeenAt < cutoff)
            .ExecuteUpdateAsync(s => s
                .SetProperty(c => c.IsActive, false)
                // Interceptors don't run here, so stamp it yourself
                .SetProperty(c => c.UpdatedAt, now), ct);
    }
}

