using Microsoft.EntityFrameworkCore;

public sealed class UpdatePrice(ShopDb db)
{
    public async Task<bool> RunAsync(
        int id, int version, decimal price, bool endSale, CancellationToken ct)
    {
        // EF Core 10: a block lambda, so setters can be added conditionally
        var updated = await db.Products
            .Where(p => p.Id == id && p.Version == version)
            .ExecuteUpdateAsync(s =>
            {
                s.SetProperty(p => p.Price, price);
                s.SetProperty(p => p.Version, p => p.Version + 1);
                if (endSale) s.SetProperty(p => p.OnSale, false);
            }, ct);
        // 0 rows: the product is gone, or someone changed it first
        return updated == 1;
    }
}
